package io.clipbridge.android;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.spec.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.util.*;
final class GroupCrypto {
    static byte[] bytes(String s){return s.getBytes(StandardCharsets.UTF_8);}
    static String b64(byte[] b){return Base64.getEncoder().encodeToString(b);}
    static byte[] un64(String s){return Base64.getDecoder().decode(s);}
    static String hash(byte[] b)throws Exception{return MediaProtocol.hex(MessageDigest.getInstance("SHA-256").digest(b));}
    static Set<String> keys(JSONObject value){Set<String> keys=new HashSet<>();Iterator<String> iterator=value.keys();while(iterator.hasNext())keys.add(iterator.next());return keys;}
    static String id(){return UUID.randomUUID().toString().replace("-","");}
    static String secret(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);return b64(b);}
    static PublicKey pub(String encoded)throws Exception{return KeyFactory.getInstance("EC").generatePublic(new X509EncodedKeySpec(un64(encoded)));}
    static PrivateKey priv(String encoded)throws Exception{return KeyFactory.getInstance("EC").generatePrivate(new PKCS8EncodedKeySpec(un64(encoded)));}
    static void member(JSONObject m)throws Exception{Protocol.id(m.getString("id"));String name=m.getString("name");if(name.isBlank()||name.length()>80||name.chars().anyMatch(Character::isISOControl))throw new IllegalArgumentException("设备名称无效");for(String key:new String[]{"signingKey","agreementKey"}){if(un64(m.getString(key)).length>256||!(((java.security.interfaces.ECPublicKey)pub(m.getString(key))).getParams().getCurve().getField().getFieldSize()==256))throw new SecurityException();}}
    static JSONObject identity(String id,String name)throws Exception{Protocol.id(id);KeyPairGenerator generator=KeyPairGenerator.getInstance("EC");generator.initialize(new ECGenParameterSpec("secp256r1"));KeyPair signing=generator.generateKeyPair(),agreement=generator.generateKeyPair();JSONObject m=new JSONObject().put("id",id).put("name",name).put("signingKey",b64(signing.getPublic().getEncoded())).put("agreementKey",b64(agreement.getPublic().getEncoded()));member(m);return new JSONObject().put("member",m).put("signingPrivate",b64(signing.getPrivate().getEncoded())).put("agreementPrivate",b64(agreement.getPrivate().getEncoded()));}
    static String sign(JSONObject identity,byte[] data)throws Exception{Signature signature=Signature.getInstance("SHA256withECDSA");signature.initSign(priv(identity.getString("signingPrivate")));signature.update(data);return b64(signature.sign());}
    static boolean verify(JSONObject member,byte[] data,String value){try{Signature signature=Signature.getInstance("SHA256withECDSA");signature.initVerify(pub(member.getString("signingKey")));signature.update(data);return signature.verify(un64(value));}catch(Exception e){return false;}}
    static boolean same(JSONObject a,JSONObject b)throws Exception{for(String key:new String[]{"id","name","signingKey","agreementKey"})if(!a.getString(key).equals(b.getString(key)))return false;return true;}
    static byte[] certData(JSONObject c)throws Exception{JSONObject m=c.getJSONObject("member");return bytes("clipbridge:group-member:1\n"+c.getString("group")+"\n"+c.getString("issuer")+"\n"+m.getString("id")+"\n"+b64(bytes(m.getString("name")))+"\n"+m.getString("signingKey")+"\n"+m.getString("agreementKey")+(c.optString("admission").isEmpty()?"":"\nclipbridge:readmission:1\n"+c.getString("admission")+"\n"+c.getString("previous")));}
    static String certHash(JSONObject c)throws Exception{return hash(bytes(b64(certData(c))+"\n"+c.getString("signature")));}
    static JSONObject certify(String group,JSONObject identity,JSONObject m)throws Exception{Protocol.id(group);member(m);JSONObject c=new JSONObject().put("group",group).put("issuer",identity.getJSONObject("member").getString("id")).put("member",m);return c.put("signature",sign(identity,certData(c)));}
    static void connection(JSONObject c)throws Exception{String type=c.optString("transport","relay");if(!Set.of("relay","webdav").contains(type))throw new IllegalArgumentException();java.net.URI u=new java.net.URI(c.getString("server"));if(!"https".equals(u.getScheme())&&!("http".equals(u.getScheme())&&Set.of("127.0.0.1","localhost").contains(u.getHost())))throw new IllegalArgumentException("请使用 HTTPS 地址");if(u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null||type.equals("relay")&&!(u.getPath().isEmpty()||u.getPath().equals("/")))throw new IllegalArgumentException("连接地址无效");if(type.equals("webdav")&&(c.optString("username").isBlank()||c.optString("username").length()>256||c.optString("username").contains(":")||c.optString("password").isEmpty()||c.optString("password").length()>1024||(c.optString("username")+c.optString("password")).chars().anyMatch(Character::isISOControl)))throw new IllegalArgumentException("WebDAV 凭据无效");}
    static JSONObject create(JSONObject identity,String name,JSONObject connection)throws Exception{connection(connection);if(name.isBlank()||name.length()>64||name.chars().anyMatch(Character::isISOControl))throw new IllegalArgumentException("同步组名称无效");String id=id();JSONObject root=certify(id,identity,identity.getJSONObject("member"));return new JSONObject().put("id",id).put("name",name).put("storageVersion",2).put("connection",connection).put("access",secret()).put("directoryKey",secret()).put("root",root).put("members",new JSONObject().put(identity.getJSONObject("member").getString("id"),root)).put("feeds",new JSONObject()).put("removed",new JSONArray()).put("ownCertificates",new JSONArray()).put("ownRemoved",new JSONArray()).put("sequence",1).put("enabled",true).put("suppressedPeers",new JSONArray()).put("publishedSequence",0).put("checkedAt",0).put("status","等待连接");}
    static boolean contains(JSONArray a,String s){for(int i=0;i<a.length();i++)if(s.equals(a.optString(i)))return true;return false;}
    static void add(JSONArray a,String s){if(!contains(a,s))a.put(s);}
    static byte[] feedData(JSONObject f)throws Exception{List<String> certs=new ArrayList<>(),removed=new ArrayList<>();JSONArray list=f.getJSONArray("certificates");for(int i=0;i<list.length();i++)certs.add(certHash(list.getJSONObject(i)));list=f.getJSONArray("removed");for(int i=0;i<list.length();i++)removed.add(list.getString(i));Collections.sort(certs);Collections.sort(removed);return bytes("clipbridge:group-feed:1\n"+f.getString("group")+"\n"+f.getString("author")+"\n"+f.getLong("sequence")+"\n"+String.join("\n",certs)+"\n"+String.join(",",removed));}
    static JSONObject feed(JSONObject g,JSONObject identity)throws Exception{JSONObject f=new JSONObject().put("group",g.getString("id")).put("author",identity.getJSONObject("member").getString("id")).put("sequence",g.getLong("sequence")).put("certificates",new JSONArray(g.getJSONArray("ownCertificates").toString())).put("removed",new JSONArray(g.getJSONArray("ownRemoved").toString()));return f.put("signature",sign(identity,feedData(f)));}
    static String revocation(JSONObject c)throws Exception{return c.getJSONObject("member").getString("id")+(c.optString("admission").isEmpty()?"":":"+c.getString("admission"));}
    static void refreshRemoved(JSONObject g)throws Exception{JSONArray revoked=g.optJSONArray("revoked");if(revoked==null)revoked=new JSONArray();JSONObject feeds=g.getJSONObject("feeds");for(String author:keys(feeds)){JSONArray tokens=feeds.getJSONObject(author).getJSONArray("removed");for(int i=0;i<tokens.length();i++)add(revoked,tokens.getString(i));}if(revoked.length()==0){JSONArray old=g.getJSONArray("removed");for(int i=0;i<old.length();i++)add(revoked,old.getString(i));}JSONArray removed=new JSONArray();JSONObject members=g.getJSONObject("members");for(String id:keys(members))if(contains(revoked,revocation(members.getJSONObject(id))))removed.put(id);g.put("revoked",revoked).put("removed",removed);}
    static void epoch(JSONObject c)throws Exception{if(c.optString("admission").isEmpty()){if(!c.optString("previous").isEmpty())throw new SecurityException();return;}Protocol.id(c.getString("admission"));if(!c.optString("previous").matches("[0-9a-f]{64}")||c.getString("issuer").equals(c.getJSONObject("member").getString("id")))throw new SecurityException("重新入组授权无效");}
    static boolean accept(JSONObject g,JSONObject f)throws Exception{refreshRemoved(g);String author=f.getString("author");Protocol.id(author);JSONObject members=g.getJSONObject("members"),feeds=g.getJSONObject("feeds");JSONArray certs=f.getJSONArray("certificates"),removed=f.getJSONArray("removed");if(!f.getString("group").equals(g.getString("id"))||f.getLong("sequence")<1||certs.length()>128||removed.length()>128)throw new SecurityException();if(contains(g.getJSONArray("removed"),author)||!members.has(author))return false;JSONObject signing=members.getJSONObject(author).getJSONObject("member");if(!verify(signing,feedData(f),f.getString("signature")))throw new SecurityException("成员清单签名无效");boolean newer=true;if(feeds.has(author)){JSONObject old=feeds.getJSONObject(author);if(f.getLong("sequence")<old.getLong("sequence"))return false;if(f.getLong("sequence")==old.getLong("sequence")){if(!MessageDigest.isEqual(feedData(f),feedData(old)))throw new SecurityException("成员清单分叉");newer=false;}}
        for(int i=0;i<certs.length();i++){JSONObject c=certs.getJSONObject(i),m=c.getJSONObject("member");member(m);epoch(c);if(!c.getString("group").equals(g.getString("id"))||!c.getString("issuer").equals(author)||!verify(signing,certData(c),c.getString("signature")))throw new SecurityException("入组授权无效");if(members.has(m.getString("id"))&&!same(members.getJSONObject(m.getString("id")).getJSONObject("member"),m))throw new SecurityException("设备身份发生变化");}
        for(int i=0;i<removed.length();i++){String[] parts=removed.getString(i).split(":",-1);if(parts.length>2)throw new SecurityException();for(String part:parts)Protocol.id(part);}
        JSONObject next=new JSONObject(members.toString());boolean changed=false;for(int i=0;i<certs.length();i++){JSONObject c=certs.getJSONObject(i);String id=c.getJSONObject("member").getString("id");if(!next.has(id)||!c.optString("admission").isEmpty()&&c.optString("previous").equals(certHash(next.getJSONObject(id)))){next.put(id,c);changed=true;}}
        JSONArray revoked=new JSONArray(g.getJSONArray("revoked").toString());for(int i=0;i<removed.length();i++)add(revoked,removed.getString(i));int active=0;for(String id:keys(next))if(!contains(revoked,revocation(next.getJSONObject(id))))active++;if(active>8||next.length()>32)throw new IllegalStateException("一个同步组最多支持 8 台设备");g.put("members",next).put("revoked",revoked);feeds.put(author,f);refreshRemoved(g);return newer||changed;
    }
    static void addMember(JSONObject g,JSONObject identity,JSONObject m)throws Exception{refreshRemoved(g);String own=identity.getJSONObject("member").getString("id"),id=m.getString("id");if(contains(g.getJSONArray("removed"),own))throw new IllegalStateException("邀请设备已被移出同步组");boolean again=contains(g.getJSONArray("removed"),id);if(g.getJSONObject("members").has(id)&&!again)throw new IllegalStateException("此设备已在同步组内");if(again&&!same(g.getJSONObject("members").getJSONObject(id).getJSONObject("member"),m))throw new SecurityException("设备身份发生变化");if(g.getJSONObject("members").length()-g.getJSONArray("removed").length()>=8||!again&&g.getJSONObject("members").length()>=32||g.getJSONArray("ownCertificates").length()>=128)throw new IllegalStateException("同步组人数或历史授权达到上限");JSONObject certificate=certify(g.getString("id"),identity,m);if(again){certificate.put("admission",id()).put("previous",certHash(g.getJSONObject("members").getJSONObject(id)));certificate.put("signature",sign(identity,certData(certificate)));}g.getJSONArray("ownCertificates").put(certificate);g.put("sequence",Math.addExact(g.getLong("sequence"),1));accept(g,feed(g,identity));}
    static void remove(JSONObject g,JSONObject identity,String id)throws Exception{refreshRemoved(g);Protocol.id(id);if(contains(g.getJSONArray("removed"),identity.getJSONObject("member").getString("id"))||!g.getJSONObject("members").has(id))throw new IllegalStateException("不能移除此设备");add(g.getJSONArray("ownRemoved"),revocation(g.getJSONObject("members").getJSONObject(id)));g.put("sequence",Math.addExact(g.getLong("sequence"),1));accept(g,feed(g,identity));}
    static void validate(JSONObject g)throws Exception{String id=g.getString("id");Protocol.id(id);refreshRemoved(g);connection(g.getJSONObject("connection"));JSONObject root=g.getJSONObject("root"),rootMember=root.getJSONObject("member"),members=g.getJSONObject("members"),valid=new JSONObject().put(rootMember.getString("id"),root);member(rootMember);if(!root.getString("group").equals(id)||!root.getString("issuer").equals(rootMember.getString("id"))||!verify(rootMember,certData(root),root.getString("signature"))||members.length()<1||members.length()>32||g.getString("name").isBlank()||g.getString("name").length()>64||un64(g.getString("directoryKey")).length!=32)throw new SecurityException();for(int pass=0;pass<32;pass++)for(String key:keys(members)){JSONObject c=members.getJSONObject(key);member(c.getJSONObject("member"));epoch(c);if(!c.getString("group").equals(id))throw new SecurityException();if(valid.has(c.getString("issuer"))&&verify(valid.getJSONObject(c.getString("issuer")).getJSONObject("member"),certData(c),c.getString("signature")))valid.put(c.getJSONObject("member").getString("id"),c);}if(valid.length()!=members.length()||!same(members.getJSONObject(rootMember.getString("id")).getJSONObject("member"),rootMember))throw new SecurityException("同步组授权链不完整");if(g.getJSONObject("connection").optString("transport").equals("relay")&&un64(g.getString("access")).length!=32)throw new SecurityException();for(String mid:keys(members)){JSONObject c=members.getJSONObject(mid);if(!valid.has(c.getString("issuer"))||!verify(valid.getJSONObject(c.getString("issuer")).getJSONObject("member"),certData(c),c.getString("signature")))throw new SecurityException("成员证书无效");}JSONObject feeds=g.getJSONObject("feeds");for(String author:keys(feeds)){JSONObject f=feeds.getJSONObject(author);if(!f.getString("group").equals(id)||!valid.has(f.getString("author"))||!verify(valid.getJSONObject(f.getString("author")).getJSONObject("member"),feedData(f),f.getString("signature")))throw new SecurityException();}}
    static byte[] hkdf(byte[] raw,byte[] salt,byte[] info)throws Exception{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(salt,"HmacSHA256"));byte[] prk=mac.doFinal(raw);mac.init(new SecretKeySpec(prk,"HmacSHA256"));mac.update(info);mac.update((byte)1);return mac.doFinal();}
    static byte[] agreement(JSONObject identity,JSONObject peer)throws Exception{KeyAgreement agreement=KeyAgreement.getInstance("ECDH");agreement.init(priv(identity.getString("agreementPrivate")));agreement.doPhase(pub(peer.getString("agreementKey")),true);return agreement.generateSecret();}
    static String storagePrefix(JSONObject g)throws Exception{return (g.optInt("storageVersion",1)>=2?"clipbridge/groups/":"clipbridge-groups/")+g.getString("id")+"/";}
    static JSONObject channel(JSONObject g,JSONObject identity,JSONObject peer)throws Exception{member(peer);String own=identity.getJSONObject("member").getString("id"),to=peer.getString("id"),first=own.compareTo(to)<0?own:to,last=first.equals(own)?to:own;String pair=hash(bytes("clipbridge:mesh-pair:1:"+g.getString("id")+":"+first+":"+last)).substring(0,32),device=hash(bytes(pair+":"+own)).substring(0,32),recipient=hash(bytes(pair+":"+to)).substring(0,32);byte[] raw=agreement(identity,peer),key=hkdf(raw,MessageDigest.getInstance("SHA-256").digest(bytes("clipbridge:group-channel:1:"+g.getString("id"))),bytes(pair));Arrays.fill(raw,(byte)0);JSONObject connection=g.getJSONObject("connection");boolean relay=connection.optString("transport").equals("relay");String server=connection.getString("server").replaceAll("/+$","")+(relay?"/v2/groups/"+g.getString("id")+"/store/":"/"+storagePrefix(g));return new JSONObject().put("server",server).put("pair",pair).put("device",device).put("peer",recipient).put("token",b64(MessageDigest.getInstance("SHA-256").digest(bytes(pair+device)))).put("key",b64(key)).put("transport","webdav").put("username",relay?"group":connection.getString("username")).put("password",relay?g.getString("access"):connection.getString("password"));}
    static JSONObject exported(JSONObject g)throws Exception{return new JSONObject(g.toString()).put("ownCertificates",new JSONArray()).put("ownRemoved",new JSONArray()).put("sequence",1).put("suppressedPeers",new JSONArray()).put("publishedSequence",0).put("checkedAt",0);}
    static JSONObject seal(byte[] key,String aad,String plain)throws Exception{byte[] nonce=new byte[12];new SecureRandom().nextBytes(nonce);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,nonce));cipher.updateAAD(bytes(aad));return new JSONObject().put("nonce",b64(nonce)).put("data",b64(cipher.doFinal(bytes(plain))));}
    static String open(byte[] key,String aad,JSONObject box)throws Exception{byte[] nonce=un64(box.getString("nonce")),data=un64(box.getString("data"));if(nonce.length!=12||data.length<16||data.length>200000)throw new SecurityException();Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,nonce));cipher.updateAAD(bytes(aad));return new String(cipher.doFinal(data),StandardCharsets.UTF_8);}
}
